    [Fact]
    public void Packet4436_DoesNotScan_LegionName_From_Wrong_Offset()
    {
        var packet = Convert.FromHexString("");
        packet[118] = 0xEF;
        packet[119] = 0x03;
        packet[120] = 0x04;
        packet[121] = (byte)'F';
        packet[122] = (byte)'a';
        packet[123] = (byte)'k';
        packet[124] = (byte)'e';
        packet[125] = 0x01;
        packet[126] = 0x00;
        packet[127] = 0x01;
        packet[128] = 0x00;

        Assert.True(Packet4436NicknameParser.TryParse(packet, out var parsed));
        Assert.Equal(string.Empty, parsed.LegionName);
    }

