    [Fact]
    public void EmbeddedIdentityScanner_Reads_4536_Metadata_From_UnknownPayload()
    {
        var packet = Convert.FromHexString("");
        var scene = new SceneLiveReadModel(DateTimeOffset.UnixEpoch);
        var sink = scene.Synchronize(SceneSinkFactory.CreateForLive(scene)());
        var writer = new SceneObservationWriter(sink);
        var ordinals = new PacketOrdinalState();
        var context = new PacketParseContext(sink, writer, ordinals, default, 1_000);

        Assert.True(PacketEmbeddedIdentityScanner.Scan(packet, ref context));
        scene.Owner.Refresh();

        Assert.True(scene.Owner.MetadataRegistry.TryGetPcMetadata(7789, out var metadata));
        Assert.Equal("蘭雨", metadata.Nickname);
        Assert.Null(metadata.OriginServerId);
        Assert.Equal(string.Empty, metadata.LegionName);
    }

    [Fact]
    public void EmbeddedIdentityScanner_Merges_3336_Name_With_2933_LegionMetadata()
    {
        var packet = Convert.FromHexString("");
        var scene = new SceneLiveReadModel(DateTimeOffset.UnixEpoch);
        var sink = scene.Synchronize(SceneSinkFactory.CreateForLive(scene)());
        var writer = new SceneObservationWriter(sink);
        var ordinals = new PacketOrdinalState();
        var context = new PacketParseContext(sink, writer, ordinals, default, 1_000);

        Assert.True(PacketEmbeddedIdentityScanner.Scan(packet, ref context));
        scene.Owner.Refresh();

        Assert.True(scene.Owner.MetadataRegistry.TryGetPcMetadata(4329, out var metadata));
        Assert.Equal("謝謝惠顧", metadata.Nickname);
        Assert.Equal(1007, metadata.OriginServerId);
        Assert.Equal("Aether", metadata.LegionName);
        Assert.True(metadata.IsLocalPlayer);
    }

